use core.files

load: fn(path: String) -> String IOError! {
    files.read(path)
}

size: fn(text: String) -> Int Never! {
    text.count_bytes()
}

run: fn() IOError! {
    first: load("a.txt")
    second: load("b.txt") ?? ""
    print(size(first) + size(second))
    files.write("c.txt", first)
    print(load("d.txt"))
}
